import copy

def check(candidate):
    defaults = {"db": {"host": "a", "port": 1, "opts": {"ssl": True}}, "tags": ["x"], "debug": False}
    overrides = {"db": {"port": 2, "opts": {"timeout": 5}}, "tags": ["y"], "debug": None, "new": 1}
    d0, o0 = copy.deepcopy(defaults), copy.deepcopy(overrides)
    result = candidate(defaults, overrides)
    assert result == {"db": {"host": "a", "port": 2, "opts": {"ssl": True, "timeout": 5}}, "tags": ["y"], "new": 1}
    assert defaults == d0 and overrides == o0
    assert candidate({"a": {"b": 1}}, {"a": 5}) == {"a": 5}
    assert candidate({"a": 5}, {"a": {"b": 1}}) == {"a": {"b": 1}}
    assert candidate({}, {"gone": None}) == {}
    r = candidate({"n": {"k": [1]}}, {})
    r["n"]["k"].append(2)
    assert candidate({"n": {"k": [1]}}, {}) == {"n": {"k": [1]}}
